messages.content:
{
  "message": "Thanks for the update. Since it still shows “No Signal” and “Data Disabled,” let’s focus on the SIM card and network registration next.",
  "keep_wifi_off_for_testing": true,
  "steps": [
    {
      "step": 1,
      "action": "reseat_sim_card",
      "instructions": "Remove and reinsert the SIM (or re-add the eSIM profile if applicable). Then proceed to reboot."
    },
    {
      "step": 2,
      "action": "reboot_device",
      "instructions": "Restart the phone completely."
    },
    {
      "step": 3,
      "action": "check_sim_status",
      "instructions": "After reboot, check SIM status and tell me what it shows.",
      "report_back": [
        "Active",
        "Missing",
        "Locked (PIN/PUK)"
      ]
    },
    {
      "step": 4,
      "action": "check_network_status",
      "instructions": "Right after checking SIM status, check network status.",
      "report_back": [
        "Signal strength (none/poor/fair/good/excellent)",
        "Network type (5G/4G/3G/2G)",
        "Mobile data enabled: yes/no",
        "Roaming: on/off",
        "Airplane mode: on/off"
      ]
    },
    {
      "step": 5,
      "condition": "If SIM status is Active but signal is still none",
      "actions": [
        {
          "action": "set_network_mode_preference",
          "mode": "4g_5g_preferred"
        },
        {
          "action": "toggle_data",
          "state": "ON"
        },
        {
          "action": "toggle_airplane_mode",
          "sequence": "ON, wait 10 seconds, then OFF"
        },
        {
          "action": "check_status_bar",
          "report_back": [
            "Any signal bars?",
            "Does it now show “Data Enabled”?"
          ]
        }
      ]
    }
  ],
  "important_notes": [
    "If SIM status shows Locked (PIN/PUK), tell me immediately — I’ll arrange SIM security assistance.",
    "If SIM status shows Missing even after reseating, tell me — we may need to arrange a SIM/eSIM replacement.",
    "Once you have signal and data, try sending an MMS again. If MMS still fails with data working, we’ll reset APN to default and reboot."
  ],
  "request": "Please perform steps 1–4 and share the exact SIM status and network status results. If you get to step 5, let me know what the status bar shows afterward."
}
